<?php require __DIR__.'/../config/config.php';require __DIR__.'/../includes/functions.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('index.php');try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT id_buku,status FROM peminjaman WHERE id_pinjam=? FOR UPDATE');$s->execute([$_POST['id']??0]);$p=$s->fetch();if($p){if($p['status']==='dipinjam')$pdo->prepare('UPDATE buku SET stok=stok+1 WHERE id_buku=?')->execute([$p['id_buku']]);$pdo->prepare('DELETE FROM peminjaman WHERE id_pinjam=?')->execute([$_POST['id']]);flash('success','Transaksi berhasil dihapus.');}else flash('warning','Transaksi tidak ditemukan.');$pdo->commit();}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Gagal menghapus transaksi.');}redirect('index.php');?>
